using System.Text.Json;
using System.Text.RegularExpressions;
using System.Numerics;

namespace Simulation;

public sealed record Mover(string Id, long X, long Velocity, string Kind = "mover", string? Target = null, string? Policy = null);
public sealed record Deferred(long At, long Sequence, long Order, string Kind, string Id, long X, long Velocity);
public sealed record Saved(long Tick, Dictionary<string, Mover> Entities, List<Deferred> Pending, long NextOrder,
    Dictionary<string,string>? Policies = null, Dictionary<string,long>? Requests = null, Dictionary<string,long>? Issued = null);

public sealed class World
{
    public long Tick;
    public Dictionary<string, Mover> Entities = new(StringComparer.Ordinal);
    public List<Deferred> Pending = [];
    public long NextOrder;
    public Dictionary<string,string> Policies = new(StringComparer.Ordinal);
    public Dictionary<string,long> Requests = new(StringComparer.Ordinal);
    public Dictionary<string,long> Issued = new(StringComparer.Ordinal);
    public Dictionary<string, Saved> Snapshots = new(StringComparer.Ordinal);
    public List<string> Effects = [];
    public List<string> Errors = [];

    public World Copy() => new()
    {
        Tick = Tick,
        Entities = Entities.ToDictionary(x => x.Key, x => x.Value with { }, StringComparer.Ordinal),
        Pending = [.. Pending], NextOrder = NextOrder,
        Policies = Policies.ToDictionary(x=>x.Key,x=>x.Value,StringComparer.Ordinal),
        Requests = Requests.ToDictionary(x=>x.Key,x=>x.Value,StringComparer.Ordinal),
        Issued = Issued.ToDictionary(x=>x.Key,x=>x.Value,StringComparer.Ordinal),
        Snapshots = Snapshots.ToDictionary(x => x.Key,
            x => new Saved(x.Value.Tick, x.Value.Entities.ToDictionary(y => y.Key, y => y.Value with { }, StringComparer.Ordinal), [.. x.Value.Pending], x.Value.NextOrder,
                Copy(x.Value.Policies), Copy(x.Value.Requests), Copy(x.Value.Issued)), StringComparer.Ordinal),
        Effects = [.. Effects], Errors = [.. Errors]
    };
    public static Dictionary<string,T> Copy<T>(Dictionary<string,T>? source) =>
        source is null ? new(StringComparer.Ordinal) : source.ToDictionary(x => x.Key, x => x.Value, StringComparer.Ordinal);
}

public static partial class Program
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = false };
    private static readonly Regex IdPattern = IdRegex();

    public static void Main()
    {
        string? line;
        while ((line = Console.ReadLine()) is not null)
        {
            if (string.IsNullOrWhiteSpace(line)) continue;
            Console.WriteLine(Handle(line));
        }
    }

    public static string Handle(string input)
    {
        World world = new();
        try
        {
            using JsonDocument doc = JsonDocument.Parse(input);
            if (!ValidRequest(doc.RootElement, out JsonElement operations)) return Serialize(new World { Errors = ["invalid_shape"] });
            for (int i = 0; i < operations.GetArrayLength(); i++) Apply(world, operations[i]);
        }
        catch (JsonException) { return Serialize(new World { Errors = ["invalid_shape"] }); }
        return Serialize(world);
    }

    private static bool ValidRequest(JsonElement root, out JsonElement operations)
    {
        operations = default;
        if (root.ValueKind != JsonValueKind.Object || root.EnumerateObject().Count() != 2 ||
            !root.TryGetProperty("version", out JsonElement version) || !root.TryGetProperty("operations", out operations) ||
            version.ValueKind != JsonValueKind.Number || !Integer(version, out long v) || v != 1 ||
            operations.ValueKind != JsonValueKind.Array || operations.GetArrayLength() > 256) return false;
        return true;
    }

    private static void Apply(World world, JsonElement operation)
    {
        if (operation.ValueKind != JsonValueKind.Object) { world.Errors.Add("invalid_shape"); return; }
        if (!operation.TryGetProperty("op", out JsonElement op) || op.ValueKind != JsonValueKind.String) { world.Errors.Add("invalid_shape"); return; }
        string name = op.GetString()!;
        if (name is not ("spawn" or "spawn_follower" or "remove" or "tick" or "save" or "load" or "enqueue" or "import_snapshot" or "register_policy" or "assign_policy" or "request" or "cancel" or "complete" or "fast_forward")) { world.Errors.Add("unknown_operation"); return; }
        if (!ShapeIsValid(operation, name)) { world.Errors.Add("invalid_shape"); return; }
        World next = world.Copy();
        try
        {
            switch (name)
            {
                case "spawn": Spawn(next, operation); break;
                case "spawn_follower": SpawnFollower(next, operation); break;
                case "remove": Remove(next, operation); break;
                case "tick": Tick(next, operation); break;
                case "save": Save(next, operation); break;
                case "load": Load(next, operation); break;
                case "enqueue": Enqueue(next, operation); break;
                case "import_snapshot": ImportSnapshot(next, operation); break;
                case "register_policy": RegisterPolicy(next, operation); break;
                case "assign_policy": AssignPolicy(next, operation); break;
                case "request": Request(next, operation); break;
                case "cancel": Cancel(next, operation); break;
                case "complete": Complete(next, operation); break;
                case "fast_forward": FastForward(next, operation); break;
            }
            world.Tick = next.Tick; world.Entities = next.Entities; world.Pending = next.Pending; world.NextOrder = next.NextOrder;
            world.Policies = next.Policies; world.Requests = next.Requests; world.Issued = next.Issued; world.Snapshots = next.Snapshots;
            world.Effects = next.Effects; world.Errors = next.Errors;
        }
        catch (OpError e) { world.Errors.Add(e.Code); }
        catch (OverflowException) { world.Errors.Add("overflow"); }
    }

    private static void Spawn(World w, JsonElement o)
    {
        RequireKeys(o, "op", "id", "x", "velocity"); string id = StringField(o, "id"); long x = NumberField(o, "x"), velocity = NumberField(o, "velocity");
        if (!IdPattern.IsMatch(id) || x is < -1_000_000 or > 1_000_000 || velocity is < -1_000_000 or > 1_000_000) throw new OpError("invalid_value");
        if (w.Entities.ContainsKey(id)) throw new OpError("duplicate_id");
        w.Entities[id] = new(id, x, velocity); w.Effects.Add($"spawn:{id}");
    }
    private static void Remove(World w, JsonElement o)
    {
        RequireKeys(o, "op", "id"); string id = StringField(o, "id"); if (!IdPattern.IsMatch(id)) throw new OpError("invalid_value");
        if (!w.Entities.Remove(id)) throw new OpError("missing_entity"); foreach (var key in w.Entities.Keys.ToList()) if (w.Entities[key].Target == id) w.Entities[key] = w.Entities[key] with { Target = null }; w.Pending.RemoveAll(x => x.Kind == "remove" && x.Id == id && x.At > w.Tick); w.Requests.Remove(id); w.Effects.Add($"remove:{id}");
    }
    private static void Tick(World w, JsonElement o)
    {
        RequireKeys(o, "op", "count"); long count = NumberField(o, "count"); if (count is < 1 or > 1000) throw new OpError("invalid_value");
        for (long i = 0; i < count; i++) { w.Tick = checked(w.Tick + 1); var due = w.Pending.Where(x => x.At == w.Tick).OrderBy(x => x.Sequence).ThenBy(x => x.Order).ToList(); w.Pending.RemoveAll(x => x.At == w.Tick); foreach (var command in due) ExecuteDeferred(w, command); var moved = new Dictionary<string, Mover>(StringComparer.Ordinal); foreach (var (id, entity) in w.Entities) { long next = entity.Kind == "mover" ? checked(entity.X + entity.Velocity) : entity.X; if (PolicyKind(w, entity) == "clamp10") next = Math.Min(next, 10); moved[id] = entity with { X = next }; } var positions = moved.ToDictionary(x => x.Key, x => x.Value.X, StringComparer.Ordinal); foreach (var (id, entity) in moved.Where(x => x.Value.Kind == "follower")) { long step = entity.Target is string target && positions.TryGetValue(target, out long tx) ? (tx > entity.X ? 1 : tx < entity.X ? -1 : 0) : 0; long next = checked(entity.X + step); if (PolicyKind(w, entity) == "clamp10") next = Math.Min(next, 10); moved[id] = entity with { X = next }; } w.Entities = moved; }
        w.Effects.Add($"tick:{count}");
    }
    private static string? PolicyKind(World w, Mover entity) =>
        entity.Policy is string name && w.Policies.TryGetValue(name, out string? kind) ? kind : null;
    private static void Save(World w, JsonElement o)
    {
        RequireKeys(o, "op", "name"); string name = NameField(o, "name");
        w.Snapshots[name] = new(w.Tick, w.Entities.ToDictionary(x => x.Key, x => x.Value with { }, StringComparer.Ordinal), [.. w.Pending], w.NextOrder,
            World.Copy(w.Policies), World.Copy(w.Requests), World.Copy(w.Issued)); w.Effects.Add($"save:{name}");
    }
    private static void Load(World w, JsonElement o)
    {
        RequireKeys(o, "op", "name"); string name = NameField(o, "name"); if (!w.Snapshots.TryGetValue(name, out var saved)) throw new OpError("missing_snapshot");
        w.Tick = saved.Tick; w.Entities = saved.Entities.ToDictionary(x => x.Key, x => x.Value with { }, StringComparer.Ordinal); w.Effects.Add($"load:{name}");
        w.Pending = [.. saved.Pending]; w.NextOrder = saved.NextOrder;
        w.Policies = saved.Policies is null ? new(StringComparer.Ordinal) : saved.Policies.ToDictionary(x=>x.Key,x=>x.Value,StringComparer.Ordinal);
        w.Requests = World.Copy(saved.Requests); w.Issued = World.Copy(saved.Issued);
    }

    private static string StringField(JsonElement o, string key) { if (!o.TryGetProperty(key, out var x) || x.ValueKind != JsonValueKind.String) throw new OpError("invalid_shape"); return x.GetString()!; }
    private static string NameField(JsonElement o, string key) { string x = StringField(o, key); if (!IdPattern.IsMatch(x)) throw new OpError("invalid_value"); return x; }
    private static long NumberField(JsonElement o, string key) { if (!o.TryGetProperty(key, out var x) || x.ValueKind != JsonValueKind.Number || !Integer(x, out long n)) throw new OpError(x.ValueKind == JsonValueKind.Number ? "invalid_value" : "invalid_shape"); return n; }
    private static bool Integer(JsonElement x, out long value) { string raw = x.GetRawText(); return long.TryParse(raw, System.Globalization.NumberStyles.AllowLeadingSign, System.Globalization.CultureInfo.InvariantCulture, out value) && raw.IndexOfAny('.', 'e', 'E') < 0; }
    private static void RequireKeys(JsonElement o, params string[] keys) { if (o.EnumerateObject().Count() != keys.Length || keys.Any(k => !o.TryGetProperty(k, out _))) throw new OpError("invalid_shape"); }
    private static bool ShapeIsValid(JsonElement o, string name)
    {
        string[] fields = name switch { "spawn" => ["op", "id", "x", "velocity"], "spawn_follower" => ["op", "id", "target", "x"], "remove" => ["op", "id"], "tick" or "fast_forward" => ["op", "count"], "enqueue" => ["op", "at", "sequence", "command"], "import_snapshot" => ["op", "name", "data"], "register_policy" => ["op","name","kind"], "assign_policy" => ["op","id","name"], "request" or "cancel" => ["op","id","sequence"], "complete" => ["op","id","sequence","value"], _ => ["op", "name"] };
        if (o.EnumerateObject().Count() != fields.Length || fields.Any(field => !o.TryGetProperty(field, out _))) return false;
        if (o.GetProperty("op").ValueKind != JsonValueKind.String) return false;
        if (name == "spawn") return o.GetProperty("id").ValueKind == JsonValueKind.String && o.GetProperty("x").ValueKind == JsonValueKind.Number && o.GetProperty("velocity").ValueKind == JsonValueKind.Number;
        if (name == "remove") return o.GetProperty("id").ValueKind == JsonValueKind.String;
        if (name == "spawn_follower") return o.GetProperty("id").ValueKind == JsonValueKind.String && o.GetProperty("target").ValueKind == JsonValueKind.String && o.GetProperty("x").ValueKind == JsonValueKind.Number;
        if (name is "tick" or "fast_forward") return o.GetProperty("count").ValueKind == JsonValueKind.Number;
        if (name == "enqueue") return o.GetProperty("at").ValueKind == JsonValueKind.Number && o.GetProperty("sequence").ValueKind == JsonValueKind.Number && o.GetProperty("command").ValueKind == JsonValueKind.Object;
        if (name == "import_snapshot") return o.GetProperty("name").ValueKind == JsonValueKind.String && o.GetProperty("data").ValueKind == JsonValueKind.Object;
        if (name == "register_policy") return o.GetProperty("name").ValueKind == JsonValueKind.String && o.GetProperty("kind").ValueKind == JsonValueKind.String;
        if (name == "assign_policy") return o.GetProperty("id").ValueKind == JsonValueKind.String && o.GetProperty("name").ValueKind == JsonValueKind.String;
        if (name is "request" or "cancel") return o.GetProperty("id").ValueKind == JsonValueKind.String && o.GetProperty("sequence").ValueKind == JsonValueKind.Number;
        if (name == "complete") return o.GetProperty("id").ValueKind == JsonValueKind.String && o.GetProperty("sequence").ValueKind == JsonValueKind.Number && o.GetProperty("value").ValueKind == JsonValueKind.Number;
        return o.GetProperty("name").ValueKind == JsonValueKind.String;
    }
    private static void RegisterPolicy(World w, JsonElement o)
    {
        string name = NameField(o, "name"), kind = StringField(o, "kind");
        if (kind != "clamp10" || !w.Policies.TryAdd(name, kind)) throw new OpError("invalid_value");
        w.Effects.Add($"register:{name}");
    }
    private static void AssignPolicy(World w, JsonElement o)
    {
        string id = StringField(o, "id"), name = NameField(o, "name");
        if (!w.Entities.ContainsKey(id)) throw new OpError("missing_entity");
        if (!w.Policies.ContainsKey(name)) throw new OpError("invalid_value");
        w.Entities[id] = w.Entities[id] with { Policy = name }; w.Effects.Add($"policy:{id}:{name}");
    }
    private static void Request(World w, JsonElement o)
    {
        string id = StringField(o, "id"); long sequence = NumberField(o, "sequence");
        if (!IdPattern.IsMatch(id) || sequence < 0) throw new OpError("invalid_value");
        if (!w.Entities.ContainsKey(id)) throw new OpError("missing_entity");
        if (w.Issued.TryGetValue(id, out long issued) && sequence <= issued) throw new OpError("invalid_value");
        w.Issued[id] = sequence; w.Requests[id] = sequence; w.Effects.Add($"request:{id}:{sequence}");
    }
    private static void Cancel(World w, JsonElement o)
    {
        string id = StringField(o, "id"); long sequence = NumberField(o, "sequence");
        if (!IdPattern.IsMatch(id) || sequence < 0) throw new OpError("invalid_value");
        if (!w.Requests.TryGetValue(id, out long pending) || pending != sequence) throw new OpError("invalid_value");
        w.Requests.Remove(id); w.Effects.Add($"cancel:{id}");
    }
    private static void Complete(World w, JsonElement o)
    {
        string id = StringField(o, "id"); long sequence = NumberField(o, "sequence"), value = NumberField(o, "value");
        if (!IdPattern.IsMatch(id) || sequence < 0 || value is < -1_000_000 or > 1_000_000) throw new OpError("invalid_value");
        if (!w.Requests.TryGetValue(id, out long pending) || pending != sequence) throw new OpError("stale_completion");
        w.Requests.Remove(id); w.Effects.Add($"complete:{id}:{value}");
    }
    private static void FastForward(World w, JsonElement o)
    {
        long count = NumberField(o, "count");
        if (count is < 1 or > 1_000_000_000) throw new OpError("invalid_value");
        if (w.Pending.Count != 0 || w.Requests.Count != 0 ||
            w.Entities.Values.Any(entity => entity.Kind != "mover" || entity.Policy is not null))
            throw new OpError("nonquiescent");
        long finalTick = checked(w.Tick + count);
        var positions = new Dictionary<string,long>(StringComparer.Ordinal);
        foreach (Mover entity in w.Entities.Values)
        {
            BigInteger final = (BigInteger)entity.X + (BigInteger)entity.Velocity * count;
            if (final < long.MinValue || final > long.MaxValue) throw new OverflowException();
            positions[entity.Id] = (long)final;
        }
        w.Tick = finalTick;
        foreach (var item in positions) w.Entities[item.Key] = w.Entities[item.Key] with { X = item.Value };
        w.Effects.Add($"fast_forward:{count}");
    }
    private static string Serialize(World w)
    {
        var result = new { version = 1, state = new { tick = w.Tick, entities = w.Entities.OrderBy(x => x.Key, StringComparer.Ordinal).Select(LiveEntity) }, effects = w.Effects, errors = w.Errors,
            snapshots = w.Snapshots.OrderBy(x => x.Key, StringComparer.Ordinal).Select(x => new { name = x.Key, data = SnapshotData(x.Value) }) };
        return JsonSerializer.Serialize(result, JsonOptions);
    }
    private static object LiveEntity(KeyValuePair<string, Mover> x) => (x.Value.Kind, x.Value.Policy) switch
    {
        ("mover", null) => new { id = x.Value.Id, x = x.Value.X, velocity = x.Value.Velocity },
        ("mover", _) => new { id = x.Value.Id, x = x.Value.X, velocity = x.Value.Velocity, policy = x.Value.Policy },
        (_, null) => new { kind = "follower", id = x.Value.Id, x = x.Value.X, velocity = 0L, target = x.Value.Target },
        _ => new { kind = "follower", id = x.Value.Id, x = x.Value.X, velocity = 0L, target = x.Value.Target, policy = x.Value.Policy }
    };
    private static object SnapshotEntity(Mover y) => (y.Kind, y.Policy) switch
    {
        ("mover", null) => new { kind = "mover", id = y.Id, x = y.X, velocity = y.Velocity },
        ("mover", _) => new { kind = "mover", id = y.Id, x = y.X, velocity = y.Velocity, policy = y.Policy },
        (_, null) => new { kind = "follower", id = y.Id, x = y.X, velocity = 0L, target = y.Target },
        _ => new { kind = "follower", id = y.Id, x = y.X, velocity = 0L, target = y.Target, policy = y.Policy }
    };
    private static object SnapshotData(Saved s) => new { version = 2, tick = s.Tick, entities = s.Entities.OrderBy(y => y.Key, StringComparer.Ordinal).Select(y => SnapshotEntity(y.Value)), pending = s.Pending.OrderBy(p => p.At).ThenBy(p => p.Sequence).ThenBy(p => p.Order).Select(p => p.Kind == "spawn" ? (object)new { at = p.At, sequence = p.Sequence, order = p.Order, command = new { op = "spawn", id = p.Id, x = p.X, velocity = p.Velocity } } : new { at = p.At, sequence = p.Sequence, order = p.Order, command = new { op = "remove", id = p.Id } }), policies = (s.Policies ?? new()).OrderBy(x => x.Key, StringComparer.Ordinal).Select(x => new { name = x.Key, kind = x.Value }), requests = (s.Requests ?? new()).OrderBy(x => x.Key, StringComparer.Ordinal).Select(x => new { id = x.Key, sequence = x.Value }), issued = (s.Issued ?? new()).OrderBy(x => x.Key, StringComparer.Ordinal).Select(x => new { id = x.Key, sequence = x.Value }) };
    private static void Enqueue(World w, JsonElement o)
    {
        long at = NumberField(o, "at"), sequence = NumberField(o, "sequence"); if (at <= w.Tick || at > 1_000_000 || sequence < 0) throw new OpError("invalid_value");
        long order = 0;
        if (w.Pending.Count != 0)
        {
            long greatest = w.Pending.Max(x => x.Order);
            order = checked(greatest + 1);
        }
        var c = o.GetProperty("command"); if (!c.TryGetProperty("op", out var op) || op.ValueKind != JsonValueKind.String) throw new OpError("invalid_shape"); string kind = op.GetString()!;
        if (kind is not ("spawn" or "remove"))
        {
            if (kind is not ("tick" or "save" or "load" or "enqueue" or "spawn_follower" or "import_snapshot" or "register_policy" or "assign_policy" or "request" or "cancel" or "complete" or "fast_forward")) throw new OpError("unknown_operation");
            if (!NestedShapeValid(c, kind)) throw new OpError("invalid_shape");
            throw new OpError("invalid_value");
        }
        string[] keys = kind == "spawn" ? ["op", "id", "x", "velocity"] : ["op", "id"]; if (c.EnumerateObject().Count() != keys.Length || keys.Any(k => !c.TryGetProperty(k, out _))) throw new OpError("invalid_shape");
        string id = StringField(c, "id"); long x = kind == "spawn" ? NumberField(c, "x") : 0, velocity = kind == "spawn" ? NumberField(c, "velocity") : 0;
        if (!IdPattern.IsMatch(id) || (kind == "spawn" && (x is < -1_000_000 or > 1_000_000 || velocity is < -1_000_000 or > 1_000_000)) || (kind == "remove" && c.GetProperty("id").ValueKind != JsonValueKind.String)) throw new OpError("invalid_value");
        w.Pending.Add(new(at, sequence, order, kind, id, x, velocity));
        w.NextOrder = order; w.Effects.Add($"enqueue:{at}:{sequence}");
    }
    private static bool NestedShapeValid(JsonElement c, string kind)
    {
        string[] fields = kind switch { "tick" or "fast_forward" => ["op","count"], "save" or "load" => ["op","name"], "enqueue" => ["op","at","sequence","command"], "spawn_follower" => ["op","id","target","x"], "import_snapshot" => ["op","name","data"], "register_policy" => ["op","name","kind"], "assign_policy" => ["op","id","name"], "request" or "cancel" => ["op","id","sequence"], "complete" => ["op","id","sequence","value"], _ => [] };
        if (!Exact(c, fields)) return false;
        return kind switch { "tick" or "fast_forward" => c.GetProperty("count").ValueKind == JsonValueKind.Number,
            "save" or "load" => c.GetProperty("name").ValueKind == JsonValueKind.String,
            "enqueue" => c.GetProperty("at").ValueKind == JsonValueKind.Number && c.GetProperty("sequence").ValueKind == JsonValueKind.Number && c.GetProperty("command").ValueKind == JsonValueKind.Object,
            "spawn_follower" => c.GetProperty("id").ValueKind == JsonValueKind.String && c.GetProperty("target").ValueKind == JsonValueKind.String && c.GetProperty("x").ValueKind == JsonValueKind.Number,
            "import_snapshot" => c.GetProperty("name").ValueKind == JsonValueKind.String && c.GetProperty("data").ValueKind == JsonValueKind.Object,
            "register_policy" => c.GetProperty("name").ValueKind == JsonValueKind.String && c.GetProperty("kind").ValueKind == JsonValueKind.String,
            "assign_policy" => c.GetProperty("id").ValueKind == JsonValueKind.String && c.GetProperty("name").ValueKind == JsonValueKind.String,
            "request" or "cancel" => c.GetProperty("id").ValueKind == JsonValueKind.String && c.GetProperty("sequence").ValueKind == JsonValueKind.Number,
            "complete" => c.GetProperty("id").ValueKind == JsonValueKind.String && c.GetProperty("sequence").ValueKind == JsonValueKind.Number && c.GetProperty("value").ValueKind == JsonValueKind.Number,
            _ => false };
    }
    private static bool Exact(JsonElement o, params string[] keys) => o.ValueKind == JsonValueKind.Object && o.EnumerateObject().Count() == keys.Length && keys.All(k => o.TryGetProperty(k, out _));
    private static void SpawnFollower(World w, JsonElement o)
    {
        RequireKeys(o, "op", "id", "target", "x"); string id = StringField(o, "id"); string target = StringField(o, "target"); long x = NumberField(o, "x");
        if (!IdPattern.IsMatch(id) || !IdPattern.IsMatch(target) || x is < -1_000_000 or > 1_000_000) throw new OpError("invalid_value");
        if (w.Entities.ContainsKey(id)) throw new OpError("duplicate_id"); if (!w.Entities.ContainsKey(target)) throw new OpError("missing_entity");
        w.Entities[id] = new(id, x, 0, "follower", target); w.Effects.Add($"spawn:{id}");
    }
    private static void ImportSnapshot(World w, JsonElement o)
    {
        string name = NameField(o, "name"); var data = o.GetProperty("data"); if (data.ValueKind != JsonValueKind.Object) throw new OpError("invalid_shape");
        bool v2 = data.TryGetProperty("version", out var ver); long t; var parsed = new Dictionary<string, Mover>(StringComparer.Ordinal);
        if (v2) { if (!Integer(ver, out long version) || version != 2) throw new OpError("snapshot_version"); if (!V2Shape(data)) throw new OpError("invalid_shape"); }
        else if (!Exact(data,"tick","entities")) throw new OpError("invalid_shape");
        if (!data.TryGetProperty("tick", out var tv) || tv.ValueKind != JsonValueKind.Number || !data.TryGetProperty("entities", out var entities) || entities.ValueKind != JsonValueKind.Array) throw new OpError("invalid_shape");
        if (!Integer(tv, out t) || t < 0) throw new OpError("invalid_value");
        var policies = new Dictionary<string,string>(StringComparer.Ordinal); if (v2 && data.TryGetProperty("policies", out var pa)) { if (pa.ValueKind != JsonValueKind.Array) throw new OpError("invalid_shape"); foreach (var p in pa.EnumerateArray()) { if (!Exact(p,"name","kind")) throw new OpError("invalid_shape"); string pn=StringField(p,"name"), pk=StringField(p,"kind"); if (!IdPattern.IsMatch(pn)||pk!="clamp10"||!policies.TryAdd(pn,pk)) throw new OpError("invalid_value"); } }
        var requests = v2 ? ParseLedger(data, "requests") : new Dictionary<string,long>(StringComparer.Ordinal);
        var issued = v2 ? ParseLedger(data, "issued") : new Dictionary<string,long>(StringComparer.Ordinal);
